{
  "scenarios": [
    {
      "id": 1,
      "title": "The Overwhelming Inbox",
      "difficulty": 2,
      "narrative": "You wake up after only 6 hours of restless sleep to find 47 unread emails, three marked 'URGENT.' Your chest tightens as you scan the subject lines—each one feels like a demand you can’t meet. The weight of expectations presses down before your day has even begun.",
      "options": [
        { "id": "A", "text": "Take five slow breaths, then sort emails by priority before responding to any.", "strategy": "Emotionally Regulated" },
        { "id": "B", "text": "Reply immediately to all urgent ones with short, defensive messages to get them off your plate.", "strategy": "Avoidant/Reactive" },
        { "id": "C", "text": "Close the inbox and go for a 10-minute walk to clear your head first.", "strategy": "Analytical (Delay for Clarity)" },
        { "id": "D", "text": "Message a trusted colleague: 'I’m swamped—can you help me triage these?'", "strategy": "Assertive (Seeking Support)" }
      ]
    },
    {
      "id": 2,
      "title": "The Support Group Silence",
      "difficulty": 3,
      "narrative": "During your weekly support group, someone shares a story that mirrors your deepest fear. The room falls silent. Everyone turns to you, expecting you to speak. Your throat closes. You feel exposed, raw—and unsure if you’re ready to be vulnerable today.",
      "options": [
        { "id": "A", "text": "Say, 'I’m not ready to share yet, but thank you for your courage.'", "strategy": "Assertive (Boundary-Setting)" },
        { "id": "B", "text": "Force yourself to speak, even if your voice shakes, to avoid seeming weak.", "strategy": "Avoidant (People-Pleasing)" },
        { "id": "C", "text": "Nod silently and journal your feelings later when you’re alone.", "strategy": "Analytical (Delayed Processing)" },
        { "id": "D", "text": "Excuse yourself to the bathroom to breathe and ground yourself.", "strategy": "Emotionally Regulated" }
      ]
    },
    {
      "id": 3,
      "title": "The Missed Deadline",
      "difficulty": 4,
      "narrative": "You missed a key project deadline due to poor sleep and mounting stress. Your manager calls you into a private meeting. Their tone is calm but firm. You know this could affect your performance review—and your self-worth is already fraying.",
      "options": [
        { "id": "A", "text": "Apologize sincerely, explain your sleep struggles, and propose a revised timeline.", "strategy": "Assertive (Transparent Communication)" },
        { "id": "B", "text": "Blame external factors to protect your image.", "strategy": "Avoidant (Deflection)" },
        { "id": "C", "text": "Listen quietly, take notes, and ask, 'What support do you need from me to prevent this?'", "strategy": "Analytical (Problem-Solving)" },
        { "id": "D", "text": "Acknowledge your frustration internally but respond with steady eye contact and a composed tone.", "strategy": "Emotionally Regulated" }
      ]
    },
    {
      "id": 4,
      "title": "The Family Dinner Tension",
      "difficulty": 5,
      "narrative": "At a family dinner, your sibling makes a passive-aggressive comment about your 'always being tired.' Others laugh it off, but it stings. You’re already running on fumes, and their words echo your own self-doubt. The table feels smaller, the air thicker.",
      "options": [
        { "id": "A", "text": "Smile and change the subject to avoid conflict.", "strategy": "Avoidant (Suppression)" },
        { "id": "B", "text": "Say calmly, 'I’ve been under a lot of stress—I’d appreciate kindness over jokes.'", "strategy": "Assertive (Direct Expression)" },
        { "id": "C", "text": "Excuse yourself to text your support group for grounding.", "strategy": "Emotionally Regulated" },
        { "id": "D", "text": "Later, reflect: 'Is this about them, or my own insecurity?'", "strategy": "Analytical (Cognitive Reframing)" }
      ]
    },
    {
      "id": 5,
      "title": "The Midnight Spiral",
      "difficulty": 6,
      "narrative": "It’s 2 a.m. You’re awake again, mind racing through tomorrow’s tasks, past mistakes, and future fears. Your phone glows with notifications you’re too anxious to open. Sleep feels like a distant country you’ve lost your passport to.",
      "options": [
        { "id": "A", "text": "Get up, write down every worry, then close the notebook and return to bed.", "strategy": "Analytical (Externalization)" },
        { "id": "B", "text": "Scroll social media to distract yourself until exhaustion wins.", "strategy": "Avoidant (Numbing)" },
        { "id": "C", "text": "Practice box breathing: inhale 4 sec, hold 4, exhale 4, hold 4.", "strategy": "Emotionally Regulated" },
        { "id": "D", "text": 'Text your support group: "Can’t sleep—anyone else up?"', "strategy": "Assertive (Connection-Seeking)" }
      ]
    },
    {
      "id": 6,
      "title": "The Unexpected Criticism",
      "difficulty": 7,
      "narrative": "A close friend says, 'You’ve been so distant lately. Are you even trying?' It lands like a slap. You’ve been pouring energy into managing stress, but they don’t see the effort—only the absence. Your instinct is to shut down or lash out.",
      "options": [
        { "id": "A", "text": "Say, 'I’m doing my best. I need understanding, not judgment.'", "strategy": "Assertive (Needs Articulation)" },
        { "id": "B", "text": "Agree with them to end the conversation quickly.", "strategy": "Avoidant (Compliance)" },
        { "id": "C", "text": "Pause, then ask, 'What made you feel that way?' to understand their perspective.", "strategy": "Analytical (Empathic Inquiry)" },
        { "id": "D", "text": "Take a slow breath and say, 'I hear you. Let’s talk when I’m calmer.'", "strategy": "Emotionally Regulated" }
      ]
    },
    {
      "id": 7,
      "title": "The Burnout Crossroads",
      "difficulty": 8,
      "narrative": "You’re offered a high-visibility project that could boost your career—but it demands 60-hour weeks. You’re already at your limit. Saying yes might break you; saying no might stall your growth. The clock ticks. Your body aches with fatigue.",
      "options": [
        { "id": "A", "text": "Accept immediately—you can’t afford to say no.", "strategy": "Avoidant (Overcommitment)" },
        { "id": "B", "text": "Decline outright to protect your health.", "strategy": "Assertive (Boundary Enforcement)" },
        { "id": "C", "text": "Ask for 24 hours to assess your capacity and propose a modified role.", "strategy": "Analytical (Strategic Negotiation)" },
        { "id": "D", "text": "Sit with the offer, journal your values, and choose alignment over urgency.", "strategy": "Emotionally Regulated (Values-Based Decision)" }
      ]
    },
    {
      "id": 8,
      "title": "The Public Mistake",
      "difficulty": 9,
      "narrative": "During a team presentation, you misquote a key statistic. A senior leader corrects you in front of everyone. Heat floods your face. Your voice wavers. The room feels like it’s shrinking. You want to disappear—or defend yourself fiercely.",
      "options": [
        { "id": "A", "text": "Laugh it off: 'Thanks for the catch—accuracy matters!' and continue.", "strategy": "Assertive (Graceful Recovery)" },
        { "id": "B", "text": "Freeze, then rush through the rest to escape the spotlight.", "strategy": "Avoidant (Flight Response)" },
        { "id": "C", "text": "Pause, correct yourself calmly, and add, 'Let me double-check that source.'", "strategy": "Analytical (Precision Focus)" },
        { "id": "D", "text": "Notice your shame, breathe, and remind yourself: 'One error ≠ my worth.'", "strategy": "Emotionally Regulated (Self-Compassion)" }
      ]
    },
    {
      "id": 9,
      "title": "The Isolation Urge",
      "difficulty": 7,
      "narrative": "After a brutal week, you cancel plans with friends, telling yourself you need space. But as night falls, the silence amplifies your stress. You crave connection but fear being a burden. Your phone sits heavy in your hand.",
      "options": [
        { "id": "A", "text": "Send a voice note: 'Having a rough week—just wanted to hear your voice.'", "strategy": "Assertive (Vulnerable Outreach)" },
        { "id": "B", "text": "Watch a comfort show alone and tell yourself it’s enough.", "strategy": "Avoidant (Isolation)" },
        { "id": "C", "text": "List three people you trust and text one a simple 'Thinking of you.'", "strategy": "Analytical (Structured Connection)" },
        { "id": "D", "text": "Do a 5-minute body scan to release tension before deciding.", "strategy": "Emotionally Regulated" }
      ]
    },
    {
      "id": 10,
      "title": "The Progress Paradox",
      "difficulty": 6,
      "narrative": "You’ve been using coping strategies for weeks—but today, stress hits harder than ever. You feel like you’ve made no progress. Doubt whispers: 'What’s the point?' The tools that once helped now feel hollow.",
      "options": [
        { "id": "A", "text": "Revisit your journal to compare today’s stress to last month’s.", "strategy": "Analytical (Evidence-Based Reflection)" },
        { "id": "B", "text": "Tell your support group: 'I’m struggling to see my growth.'", "strategy": "Assertive (Seeking Validation)" },
        { "id": "C", "text": "Sit with the discomfort without judging it—just observe.", "strategy": "Emotionally Regulated (Mindful Acceptance)" },
        { "id": "D", "text": "Skip your routine today—you’re too tired to try.", "strategy": "Avoidant (Disengagement)" }
      ]
    }
  ]
}
